export const cleanStudyName=value=>typeof value==='string'?value.replace(/\s+/g,' ').trim().slice(0,80):'';
export const cleanStudyNote=value=>typeof value==='string'?value.trim().slice(0,1200):'';
export function parseStudyPackage(text,validState){
 if(typeof text!=='string'||text.length>1048576)throw new Error('size');let data;try{data=JSON.parse(text)}catch{throw new Error('json')}
 if(!data||![3,4].includes(data.version)||!data.state||typeof data.state!=='object'||Array.isArray(data.state))throw new Error('version');
 if(Object.keys(data.state).some(k=>!Object.hasOwn(defaults,k)&&k!=='objective')||!Number.isInteger(data.state.floors)||(data.version===4&&typeof data.state.led!=='boolean')||(data.state.objective!==undefined&&!['contribution','rent','yieldOnCost','corners','facade','silhouette'].includes(data.state.objective)))throw new Error('state');
 if(data.version===4&&(!data.contextStudies?.brief?.inputs||!data.contextStudies?.environment?.inputs))throw new Error('inputs');
 if(data.study&&((data.study.name!==undefined&&typeof data.study.name!=='string')||(data.study.note!==undefined&&typeof data.study.note!=='string')))throw new Error('metadata');
 const state=structuredClone(data.state);if(data.version===3){for(const[k,v]of Object.entries({material:'float',crown:'flat',garden:'none',led:false,detail:'drained-cavity'}))if(!Object.hasOwn(state,k))state[k]=v}
 if(typeof state.led!=='boolean'||!validState(state))throw new Error('state');
 const brief=normalizeBriefInputs(data.contextStudies?.brief?.inputs??{}),environment=validateEnvironment(data.contextStudies?.environment?.inputs??{});
 if(!brief||!environment)throw new Error('inputs');
 return {version:2,name:cleanStudyName(data.study?.name),note:cleanStudyNote(data.study?.note),state,brief,environment:{inputs:environment,teaching:data.contextStudies?.environment?.teaching===true},savedAt:new Date().toISOString()};
}
export function compareStudies(reference,current){
 const before=evaluate(reference.state),after=evaluate(current.state),keys=['gross','rentable','efficiency','heightTotal','facade','daylitFraction','contribution','capex'];
 return {before,after,sameArea:Math.abs(before.gross-after.gross)<.5,sameCity:reference.state.city===current.state.city,scenarioChanges:['rent','premium','occupancy','reserve','regime','city','led'].filter(k=>reference.state[k]!==current.state[k]).map(key=>({key,before:reference.state[key],after:current.state[key]})),rows:keys.map(key=>({key,before:before[key],after:after[key],delta:after[key]-before[key]}))};
}
